2000	    /// Whether each property of `listed` is `readonly`: what the property answer settles
2001	    /// ([`SymbolInfo::settled_readonly`]), and the checker's answer for the rest. Kept by (handle, listing) like every
2002	    /// answer about a list, so a list read again is not worked out again; a list the answer settles entirely sends
2003	    /// nothing. The only caller is past the size budget, so a cut object's properties are not classified.
2004	    async fn readonly(&self, listed: (u64, Listing), properties: &[SymbolInfo]) -> Result<Arc<[bool]>, CallError> {
2005	        let readonly = self
2006	            .state
2007	            .readonly
2008	            .get(listed, || async {
2009	                let settled: Vec<_> = properties.iter().map(SymbolInfo::settled_readonly).collect();
2010	                let asked: Vec<_> = properties
2011	                    .iter()
2012	                    .zip(&settled)
2013	                    .filter(|(_, settled)| settled.is_none())
2014	                    .map(|(property, _)| &property.reference)
2015	                    .collect();
2016	                let mut answers = if asked.is_empty() {
2017	                    Vec::new().into_iter()
2018	                } else {
2019	                    self.rpc.readonly_symbols(&asked).await?.into_iter()
2020	                };
2021	                let readonly: Option<Arc<[bool]>> =
2022	                    settled.iter().map(|settled| settled.or_else(|| answers.next())).collect();
2023	                let readonly =
2024	                    readonly.ok_or_else(|| CallError::Rejected("a short isReadonlySymbol batch".to_string()))?;
2025	                if answers.next().is_some() {
2026	                    return Err(CallError::Rejected("a long isReadonlySymbol batch".to_string()));
2027	                }
2028	                Ok(readonly)
2029	            })
2030	            .await?;
2031	        // `listed` names the same symbol list every time, so the cached flags are one per property.
2032	        debug_assert_eq!(readonly.len(), properties.len(), "the cached readonly flags are of another list");
2033	        Ok(readonly)
2034	    }
